.cardgen-wrap{max-width:1050px;margin:24px auto;padding:0 18px}.cardgen-panel{background:#fff;border:1px solid #e1e7f0;border-radius:14px;padding:22px;margin:18px 0}.cardgen-form{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.cardgen-form label{display:flex;flex-direction:column;gap:7px;font-weight:700;min-width:260px;flex:1}.cardgen-form select{min-height:44px;border:1px solid #ccd5e2;border-radius:9px;padding:10px;font:inherit}.student-id-card{width:340px;min-height:210px;box-sizing:border-box;border:2px solid #1e3a5f;border-radius:14px;overflow:hidden;background:#fff;margin:24px auto;box-shadow:0 6px 18px rgba(15,23,42,.12);color:#172033}.id-card-head{background:#1e3a5f;color:#fff;display:flex;align-items:center;gap:10px;padding:12px}.id-card-logo{width:44px;height:44px;object-fit:contain;background:#fff;border-radius:6px;padding:3px;box-sizing:border-box}.id-card-school{font-size:15px;font-weight:800}.id-card-subtitle{font-size:11px;opacity:.9;margin-top:3px}.id-card-body{padding:14px}.id-card-student-number{direction:ltr;text-align:center;font-size:23px;font-weight:900;letter-spacing:1px;color:#1e3a5f;border:1px dashed #94a3b8;border-radius:8px;padding:8px;margin-bottom:12px}.id-card-detail{display:grid;grid-template-columns:90px 1fr;gap:7px;font-size:12px;margin:7px 0}.id-card-label{color:#64748b}.id-card-footer{background:#f1f5f9;padding:8px 12px;font-size:10px;display:flex;justify-content:space-between;gap:8px}.cardgen-hint{color:#64748b;line-height:1.8}@media print{body{background:#fff!important}.admin-sidebar,.admin-main>header,.admin-main>.topbar,.cardgen-panel,.cardgen-wrap>header,.cardgen-hint,.cardgen-actions{display:none!important}.admin-layout,.admin-main{display:block!important;margin:0!important;padding:0!important;width:auto!important}.cardgen-wrap{margin:0;padding:0;max-width:none}.student-id-card{margin:10mm auto;box-shadow:none;break-inside:avoid;-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style></head><body class="profile-page"><div class="admin-layout"><?php require __DIR__.'/includes/sidebar.php';?><main class="admin-main"><?php require __DIR__.'/includes/topbar.php';?><div class="cardgen-wrap"><header class="page-header"><p class="eyebrow">مدیریت دانش‌آموزان</p><h1>کارت هویت شاگرد</h1><p class="cardgen-hint">شماره دائمی شاگرد در کارت نمایش داده می‌شود و در سال‌های تعلیمی بعدی تغییر نمی‌کند.</p></header>
<section class="cardgen-panel"><form class="cardgen-form" method="get"><label for="student_id">انتخاب شاگرد<select id="student_id" name="student_id" required><option value="">یک شاگرد انتخاب کنید</option><?php foreach($students as $s):?><option value="<?=(int)$s['id']?>" <?=(int)$s['id']===$studentId?'selected':''?>><?=student_card_h($s['student_number'].' — '.$s['first_name'].' '.$s['last_name'].($s['father_name']?'، ولد '.$s['father_name']:''))?></option><?php endforeach;?></select></label><button class="button button-primary" type="submit">نمایش کارت</button></form></section>
<?php if($student):?><section class="student-id-card" aria-label="کارت هویت شاگرد"><div class="id-card-head"><?php if(!empty($school['logo_path'])):?><img class="id-card-logo" src="<?=student_card_h($school['logo_path'])?>" alt="لوگوی مکتب"><?php endif;?><div><div class="id-card-school"><?=student_card_h($school['school_name']??'مکتب')?></div><div class="id-card-subtitle">کارت هویت شاگرد</div></div></div><div class="id-card-body"><div class="id-card-student-number"><?=student_card_h($student['student_number'])?></div><div class="id-card-detail"><span class="id-card-label">نام شاگرد</span><strong><?=student_card_h($student['first_name'].' '.$student['last_name'])?></strong></div><div class="id-card-detail"><span class="id-card-label">نام پدر</span><strong><?=student_card_h($student['father_name']?:'—')?></strong></div><div class="id-card-detail"><span class="id-card-label">صنف</span><strong><?=student_card_h(isset($student['grade'])&&$student['grade']!==null?($student['grade'].' '.($student['section_name']??'')):($student['class_name']?:'—'))?></strong></div><div class="id-card-detail"><span class="id-card-label">سال تعلیمی</span><strong><?=student_card_h($student['year_name']??'—')?></strong></div></div><div class="id-card-footer"><span><?=student_card_h($school['school_phone_1']??'')?></span><span><?=student_card_h($school['school_address']??'')?></span></div></section><div class="cardgen-actions" style="text-align:center"><button class="button button-primary" type="button" onclick="window.print()">چاپ کارت</button></div><?php elseif($studentId>0):?><section class="cardgen-panel">شاگرد موردنظر پیدا نشد یا پرونده او غیرفعال است.</section><?php else:?><p class="cardgen-hint">شاگرد را انتخاب کنید تا کارت با شماره دائمی او نمایش داده شود.</p><?php endif;?>
</div></main></div><script src="assets/js/sidebar-clock.js" defer></script><script src="assets/js/sidebar-submenus.js" defer></script></body></html>